import React, { useEffect, useState } from "react";
import { NavLink } from "react-router-dom";

type Task = { id:number; text:string; completed:boolean; };

function emailMeSummary() {
  const KEY_V4 = "task-tracker.tasks.v4";
  const KEY_V3 = "task-tracker.tasks.v3";
  const raw = localStorage.getItem(KEY_V4) ?? localStorage.getItem(KEY_V3) ?? "[]";
  let tasks: Task[] = [];
  try { tasks = JSON.parse(raw) as Task[]; } catch {}

  let to = localStorage.getItem("eskinder.email") ?? "";
  if (!to) {
    const entered = window.prompt("Enter your email for summaries:\n", "eskinder@example.com");
    if (!entered) return;
    to = entered.trim();
    localStorage.setItem("eskinder.email", to);
  }

  const total = tasks.length;
  const done = tasks.filter(t => t.completed).length;
  const top = tasks.slice(0,5).map(t => `- ${t.text}${t.completed ? " (done)" : ""}`);

  const subject = encodeURIComponent("Your Task Tracker Summary");
  const body = encodeURIComponent([
    "Hi Eskinder,",
    "",
    "Here is your Task Tracker summary:",
    `- Total tasks: ${total}`,
    `- Completed: ${done}`,
    "",
    "Top items:",
    ...top,
    "",
    "- AstraFocus Nexus",
  ].join("\n"));

  window.location.href = `mailto:${to}?subject=${subject}&body=${body}`;
}

const navLinkClass = ({ isActive }: { isActive: boolean }) =>
  "nav__link" + (isActive ? " nav__link--active" : "");

const Nav: React.FC = () => {
  const [perm, setPerm] = useState<NotificationPermission | "unsupported">("default");
  const [theme, setTheme] = useState<string>(() => {
    try { return localStorage.getItem('task-tracker.theme') || 'dark'; } catch { return 'dark'; }
  });

  useEffect(() => {
    if (!("Notification" in window)) setPerm("unsupported");
    else setPerm(Notification.permission);
  }, []);

  useEffect(() => {
    const root = document.documentElement;
    if (theme === 'light') root.classList.add('theme-light');
    else root.classList.remove('theme-light');
    try { localStorage.setItem('task-tracker.theme', theme); } catch {}
  }, [theme]);

  const testNotify = () => {
    if (!("Notification" in window)) return;
    if (Notification.permission !== "granted") return;
    try { new Notification("Notifications enabled", { body: "You'll get alerts from the app." }); } catch {}
  };

  const request = async () => {
    if (!("Notification" in window)) { alert("Notifications are not supported in this browser."); return; }
    if (Notification.permission === "denied") {
      setPerm("denied");
      alert([
        "Notifications are blocked for this site.",
        "To enable: click the lock icon in the address bar -> Site settings -> Notifications -> Allow.",
      ].join("\n"));
      return;
    }
    const p = await Notification.requestPermission();
    setPerm(p);
    if (p !== "granted") alert("Notification permission denied.");
    else testNotify();
  };

  const brandClass = ({ isActive }: { isActive: boolean }) =>
    "nav__brand" + (isActive ? " nav__brand--active" : "");

  return (
    <header className="site-header">
      <nav className="nav" aria-label="Main navigation">
        <NavLink to="/" end className={brandClass} title="AstraFocus Nexus home">
          AstraFocus <span className="nav__brand-accent">Nexus</span>
        </NavLink>

        <div className="nav__primary">
          <NavLink to="/" end className={navLinkClass}>
            <span className="nav__link-icon" aria-hidden>🏠</span>
            <span className="nav__link-label">Home</span>
          </NavLink>
          <NavLink to="/wellness" className={navLinkClass} role="menuitem">
            <span className="nav__link-icon" aria-hidden>🧠</span>
            <span className="nav__link-label">Wellness</span>
          </NavLink>
          <NavLink to="/matrix" className={navLinkClass} role="menuitem">
            <span className="nav__link-icon" aria-hidden>🧭</span>
            <span className="nav__link-label">Matrix</span>
          </NavLink>
          <NavLink to="/goals" className={navLinkClass} role="menuitem">
            <span className="nav__link-icon" aria-hidden>🎯</span>
            <span className="nav__link-label">Goals</span>
          </NavLink>
          <NavLink to="/about" className={navLinkClass} role="menuitem">
            <span className="nav__link-icon" aria-hidden>ℹ️</span>
            <span className="nav__link-label">About</span>
          </NavLink>
          <NavLink to="/faq" className={navLinkClass} role="menuitem">
            <span className="nav__link-icon" aria-hidden>❓</span>
            <span className="nav__link-label">FAQ</span>
          </NavLink>
        </div>

        <div className="nav__actions" aria-label="Tools">
          <button type="button" className="icon-btn" onClick={request} title="Enable notifications" aria-label={perm === "granted" ? "Notifications on" : "Enable notifications"}>
            <span className="nav__action-icon" aria-hidden>{perm === "granted" ? "🔔" : "🔕"}</span>
          </button>
          <button type="button" className="icon-btn" onClick={emailMeSummary} title="Email me a summary" aria-label="Email me a summary">
            <span className="nav__action-icon" aria-hidden>📧</span>
          </button>
          <button type="button" className="theme-toggle" onClick={()=>setTheme(theme==='light'?'dark':'light')} title="Toggle theme" aria-label={theme==='light' ? "Switch to dark theme" : "Switch to light theme"}>
            <span className="nav__action-icon" aria-hidden>{theme==='light' ? '🌞' : '🌙'}</span>
          </button>
        </div>

        <p className="nav__owner">Eskinder Kassahun · 2026</p>
      </nav>
    </header>
  );
};

export default Nav;
